package com.benabdallah.csvpipeline.api; import com.benabdallah.csvpipeline.application.*; import java.net.URI; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(NotFoundException.class) ProblemDetail notFound(NotFoundException e){return problem(HttpStatus.NOT_FOUND,"Upload not found",e);} @ExceptionHandler(ConflictException.class) ProblemDetail conflict(ConflictException e){return problem(HttpStatus.CONFLICT,"Request conflict",e);} @ExceptionHandler({IllegalArgumentException.class,MethodArgumentNotValidException.class}) ProblemDetail badRequest(Exception e){return problem(HttpStatus.BAD_REQUEST,"Invalid request",e);} private ProblemDetail problem(HttpStatus s,String title,Exception e){var p=ProblemDetail.forStatusAndDetail(s,e.getMessage());p.setTitle(title);p.setType(URI.create("https://errors.example.com/csv-pipeline/"+s.value()));return p;} }
